SELECT a.id AS attachment_db_id, m.provider_id as email_provider_id, a.provider_attachment_id as provider_attachment_id, a.filename as filename, a.mime_type as mime_type, m.internal_date_ts as internal_date_ts, m.id as message_db_id, m.thread_id as thread_db_id, from_contact.email_address as sender_email, m.subject as subject FROM email_attachments a JOIN email_messages m ON a.message_id = m.id JOIN email_contacts from_contact ON m.from_contact_id = from_contact.id WHERE m.thread_id = $1 -- attachment mime type filters injected below AND a.reference_url IS NULL AND (a.mime_type LIKE 'image/%' OR a.mime_type LIKE 'video/%') ORDER BY a.id
